// #12: the customer discount is applied once
test('customer discount is applied once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8550); // 10000 * 0.9 * 0.95
});

test('9 lines get no bulk discount', () => {
  const lines = Array.from({ length: 9 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8100);
});

test('a discounted total drops the fraction of a yen', () => {
  assert.equal(total([{ price: 995, qty: 1 }], 0.1), 895); // 895.5
  assert.equal(total([{ price: 999, qty: 1 }], 0.1), 899); // 899.1
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines, 0.1), 94); // 110 * 0.9 * 0.95 = 94.05
});

test('an exact discounted total is not cut down by float error', () => {
  assert.equal(total([{ price: 90, qty: 1 }], 0.3), 63); // 62.99999999999999 in floats
  assert.equal(total([{ price: 330, qty: 1 }], 0.3), 231);
});

test('totals without a customer discount are unchanged', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0), 1000);
  const lines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0), 9500);
});
